// jQuery jVectorMap Minimizado - Versão local simplificada
// Compatível com Brasil (br_mill)

if (typeof jvm === 'undefined') {
    window.jvm = {};
}

if (typeof jvm.WorldMap === 'undefined') {
    jvm.WorldMap = function() {};
}

// Registrar o mapa do Brasil
if (typeof $.fn.vectorMap === 'undefined') {
    $.fn.vectorMap = function(options) {
        return this.each(function() {
            var $el = $(this);
            var mapName = options.map || 'world';
            
            // Criar SVG simples do Brasil
            var width = $el.width() || 400;
            var height = $el.height() || 300;
            
            var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
            svg.setAttribute('width', width);
            svg.setAttribute('height', height);
            svg.setAttribute('viewBox', '0 0 1000 1000');
            svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
            svg.style.width = '100%';
            svg.style.height = 'auto';
            
            $el.html('');
            $el.append(svg);
            
            // Estados do Brasil (coordenadas simplificadas)
            var estados = {
                'AC': { name: 'Acre', x: 150, y: 600 },
                'AL': { name: 'Alagoas', x: 750, y: 450 },
                'AP': { name: 'Amapá', x: 550, y: 50 },
                'AM': { name: 'Amazonas', x: 250, y: 200 },
                'BA': { name: 'Bahia', x: 750, y: 500 },
                'CE': { name: 'Ceará', x: 750, y: 350 },
                'DF': { name: 'Distrito Federal', x: 650, y: 600 },
                'ES': { name: 'Espírito Santo', x: 800, y: 650 },
                'GO': { name: 'Goiás', x: 600, y: 550 },
                'MA': { name: 'Maranhão', x: 700, y: 350 },
                'MT': { name: 'Mato Grosso', x: 450, y: 550 },
                'MS': { name: 'Mato Grosso do Sul', x: 550, y: 650 },
                'MG': { name: 'Minas Gerais', x: 750, y: 650 },
                'PA': { name: 'Pará', x: 450, y: 300 },
                'PB': { name: 'Paraíba', x: 800, y: 400 },
                'PR': { name: 'Paraná', x: 700, y: 800 },
                'PE': { name: 'Pernambuco', x: 800, y: 400 },
                'PI': { name: 'Piauí', x: 700, y: 400 },
                'RJ': { name: 'Rio de Janeiro', x: 800, y: 750 },
                'RN': { name: 'Rio Grande do Norte', x: 800, y: 350 },
                'RS': { name: 'Rio Grande do Sul', x: 650, y: 900 },
                'RO': { name: 'Rondônia', x: 200, y: 500 },
                'RR': { name: 'Roraima', x: 350, y: 100 },
                'SC': { name: 'Santa Catarina', x: 700, y: 850 },
                'SP': { name: 'São Paulo', x: 700, y: 750 },
                'SE': { name: 'Sergipe', x: 800, y: 450 },
                'TO': { name: 'Tocantins', x: 500, y: 400 }
            };
            
            // Criar regiões (círculos simplificados como proxy dos estados)
            $.each(estados, function(code, data) {
                var circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
                circle.setAttribute('cx', data.x);
                circle.setAttribute('cy', data.y);
                circle.setAttribute('r', '25');
                circle.setAttribute('id', 'BR-' + code);
                circle.setAttribute('class', 'jvectormap-region estado');
                circle.setAttribute('data-code', code);
                circle.setAttribute('fill', options.regionStyle?.initial?.fill || '#014BA0');
                circle.setAttribute('stroke', '#fff');
                circle.setAttribute('stroke-width', '1');
                circle.style.cursor = 'pointer';
                circle.style.transition = 'fill 0.3s ease';
                
                // Tooltip
                var title = document.createElementNS('http://www.w3.org/2000/svg', 'title');
                title.textContent = data.name;
                circle.appendChild(title);
                
                // Eventos de mouse
                circle.addEventListener('mouseenter', function() {
                    if (options.regionStyle?.hover?.fill) {
                        circle.setAttribute('fill', options.regionStyle.hover.fill);
                    }
                });
                
                circle.addEventListener('mouseleave', function() {
                    circle.setAttribute('fill', options.regionStyle?.initial?.fill || '#014BA0');
                });
                
                circle.addEventListener('click', function(e) {
                    if (options.onRegionClick) {
                        options.onRegionClick(e, code);
                    }
                });
                
                svg.appendChild(circle);
            });
            
            // Armazenar referência ao mapa para acesso posterior
            $el.data('vectorMap', {
                getRegions: function() {
                    return estados;
                },
                clearSelectedRegions: function() {
                    svg.querySelectorAll('.jvectormap-region').forEach(function(el) {
                        el.setAttribute('fill', options.regionStyle?.initial?.fill || '#014BA0');
                    });
                }
            });
        });
    };
}

console.log('✓ jVectorMap local carregado com sucesso');